const body = $node['Webhook Slots'].json.body || {};
const duration = Math.max(15, Number(body.durationMin || 30));
const dateStr = body.date || new Date().toISOString().slice(0,10);
const [y,m,d] = dateStr.split('-').map(Number);
const start = new Date(Date.UTC(y, m - 1, d, 12, 0, 0));
const slots = [];
for (let i = 0; i < 3; i++) {
  const s = new Date(start.getTime() + i * 60 * 60 * 1000);
  const e = new Date(s.getTime() + duration * 60 * 1000);
  slots.push({ start: s.toISOString(), end: e.toISOString(), label: s.toISOString() });
}
return [{ json: { ok: true, provider: 'n8n-scheduling', leadId: body.leadId || null, slots } }];
